  	  const COMMENT = { variants: [
  	    hljs.COMMENT(';', '$', { relevance: 0 }),
  	    hljs.COMMENT('#cs', '#ce'),
  	    hljs.COMMENT('#comments-start', '#comments-end')
  	  ] };

  	  const VARIABLE = { begin: '\\$[A-z0-9_]+' };

